/// <summary>
/// Data contract class to cosider update all customer or only uploaded customer email
/// MET_86267_CustomerStatementReport developed by ydavapa on 16th Oct 2023.
/// </summary>
[   DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(MET_CustomerStatmentReportUIBuilder))
]
public class MET_CustomerStatmentReportContract
{
    AccountNum  accountNum;
    boolean     includeAllCustomer;
    container   storageResult;

}

Method.Source:
    /// <summary>
    /// Parameter method which holds values of the packed variables from <c>FileUploadTemporaryStorageResult</c> class
    /// </summary>
    /// <param name = "_storageResult">Packed instance of <c>FileUploadTemporaryStorageResult</c> class</param>
    /// <returns>Container with packed values</returns>
    //[DataMemberAttribute('Customer email update upload')]
    [DataMemberAttribute,SysOperationLabelAttribute(literalStr("@MET:CustomerEmailUpdateUpload")),SysOperationDisplayOrderAttribute('2')]
    public container parmStorageResult(container _storageResult =  storageResult)
    {
        storageResult = _storageResult;

        return storageResult;
    }

    /// <summary>
    /// Created parm method to cosider update all customer or only uploaded customer email
    /// </summary>
    /// <param name = "_includeAllCustomer">Boolean</param>
    /// <returns>Boolean value</returns>
    [DataMemberAttribute,SysOperationLabelAttribute(literalStr("@MET:IncludeAllCustomer")),SysOperationDisplayOrderAttribute('1')]
    public boolean parmIncludeAllCustomer(boolean _includeAllCustomer = includeAllCustomer)
    {
        includeAllCustomer = _includeAllCustomer;

        return includeAllCustomer;
    }
